from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])
    cnt = Counter(c for r in grid for c in r)
    bg = cnt.most_common(1)[0][0]
    mixed = [any(c != bg for c in r) for r in grid]
    # contiguous blocks of mixed rows
    blocks, cur = [], []
    for i, m in enumerate(mixed):
        if m: cur.append(i)
        elif cur: blocks.append(cur); cur = []
    if cur: blocks.append(cur)
    out = [r[:] for r in grid]
    if len(blocks) < 2: return out
    top, bot = blocks[0], blocks[-1]
    pat = next(c for c in grid[top[0]] if c != bg)
    for k, br in enumerate(bot):
        tr = top[k % len(top)]
        best = None
        for d in range(W):
            src = grid[tr]
            on_bg, bad = [], 0
            for c in range(W):
                s = c - d
                if grid[br][c] == pat:
                    if s < 0 or s >= W or src[s] != pat: bad += 1
                elif src[s] == pat if 0 <= s < W else False:
                    on_bg.append(c)
            key = (bad, len(on_bg), d)
            if best is None or key < best[0]: best = (key, d, on_bg)
        _, d, on_bg = best
        for c in on_bg: out[br][c] = 1
    return out

